import {photos,niches,videos,services,gallery,socials} from './content.js';
export const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function photo(key, sizes='(min-width: 900px) 35vw, 80vw', className='') {
  const p=photos[key];
  if(!p) return `<img class="${className}" src="${esc(key)}" alt="" loading="lazy" width="900" height="1200">`;
  return `<img class="${className}" src="/assets/photos/liza-${p.id}-960.webp" srcset="/assets/photos/liza-${p.id}-480.webp 480w, /assets/photos/liza-${p.id}-960.webp 960w, /assets/photos/liza-${p.id}-1440.webp 1440w" sizes="${sizes}" width="900" height="1200" loading="lazy" decoding="async" alt="${esc(p.alt)}">`;
}
const top=(number,label,end)=>`<div class="section-topline micro"><span>${number} / ${label}</span><span>${end}</span></div>`;
function About(){return `<section class="about section" id="about"><div class="wrap">${top('01','Обо мне','THE GIRL BEHIND THE CONTENT')}<div class="about-layout"><div class="about-collage reveal"><figure class="about-photo">${photo('summer')}<figcaption class="micro">ЛИЗА / В СВОЁМ РИТМЕ</figcaption></figure><span class="about-stamp" aria-hidden="true">a little<br><i>more me</i></span><span class="about-doodle handwritten">это я, без сценария</span></div><div class="about-copy reveal"><h2>Давайте<br><em>знакомиться.</em></h2><p class="about-lead">Я Лиза — лайфстайл<br>и UGC-креатор.</p><p>Создаю живой, эстетичный и нативный контент о красоте, стиле, повседневной жизни и маленьких вещах, которые делают её интереснее.</p><p>Мне важно, чтобы реклама не выбивалась из контента, а становилась его естественной частью. Поэтому я стараюсь не просто показать продукт, а придумать историю и подачу, через которые он действительно заинтересует аудиторию.</p><blockquote>Эстетика, естественность,<br><span class="handwritten">ощущение разговора с подругой.</span></blockquote></div></div></div></section>`}
function Contents(){return `<section class="contents section" id="contents" aria-labelledby="contents-title"><div class="wrap">${top('02','Внутри портфолио','SIDE A / SIDE B')}<div class="contents-layout"><div class="contents-copy"><h2 id="contents-title">На одной<br><em>волне.</em></h2><p>Выберите, с чего начнём.</p><span class="handwritten contents-note">мой маленький мир</span></div><div class="record-scene reveal"><img class="record" src="/assets/vinyl.webp" width="1100" height="1100" loading="lazy" alt=""><span class="record-center micro" aria-hidden="true">LIZA<br>PERSONAL<br>SELECTION</span><nav class="record-links" aria-label="Разделы портфолио"><a href="#about"><small>01</small>Обо мне</a><a href="#niches"><small>02</small>Направления</a><a href="#work"><small>03</small>Работы</a><a href="#services"><small>04</small>Что я создаю</a><a href="#contact"><small>05</small>Контакты</a></nav><span class="scene-star star-one" aria-hidden="true">✦</span><span class="scene-star star-two" aria-hidden="true">✳</span></div><img class="camera" src="/assets/camera.webp" width="1100" height="734" loading="lazy" alt="" aria-hidden="true"><span class="contents-sticker" aria-hidden="true">GOOD<br>THINGS<br><i>inside</i></span></div></div></section>`}
function Niches(){return `<section class="niches section" id="niches"><div class="wrap">${top('03','Мои направления','A FEW THINGS I LOVE')}<h2 class="reveal">То, что мне <em>близко.</em></h2><div class="niche-editorial"><div class="niche-photos reveal"><figure class="niche-photo-main">${photo('mirror')}<figcaption class="handwritten">всё начинается с интереса</figcaption></figure><figure class="niche-photo-small">${photo('flowers','(min-width: 900px) 15vw, 36vw')}</figure><span class="niche-spark" aria-hidden="true">✳</span></div><div class="niche-list">${niches.map((n,i)=>`<article class="niche-row reveal"><span class="micro">0${i+1}</span><div><h3>${n.name}</h3>${n.description?`<p>${n.description}</p>`:''}</div></article>`).join('')}</div></div></div></section>`}
function Work(){return `<section class="work section" id="work"><div class="wrap">${top('04','Работы','SELECTED UGC')}<div class="work-heading reveal"><h2>Смотреть.<br><em>Чувствовать.</em></h2><div><span class="handwritten">в кадре — жизнь</span><p class="work-draft">Видео скоро появятся.<br>Пока здесь — фотографии и превью будущих работ.</p></div></div><div class="video-grid">${videos.map((v,i)=>`<article class="video-card reveal"><button class="video-preview" data-video="${i}" aria-label="${esc(v.title)}${v.src?' — смотреть видео':' — открыть превью'}">${photo(v.poster,'(min-width: 900px) 22vw, 30vw')}<span class="video-number micro">${v.id}</span><span class="play-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 5 20 12 9 19Z"/></svg></span>${!v.src?'<span class="video-soon">СКОРО</span>':''}</button><h3>${esc(v.title)}</h3><p>${esc(v.category)}</p></article>`).join('')}</div><div class="work-foot micro"><span>МАЛЕНЬКИЕ ИСТОРИИ, КОТОРЫЕ ХОЧЕТСЯ ДОСМОТРЕТЬ</span><span>12 / SELECTED MOMENTS</span></div></div></section>`}
function Services(){return `<section class="services section" id="services"><div class="wrap">${top('05','Что я создаю','LET’S MAKE IT FEEL REAL')}<div class="services-heading reveal"><h2>От первого кадра<br><em>до «сохранить».</em></h2><span class="handwritten">с идеей и настроением</span></div><div class="services-layout"><figure class="services-photo reveal">${photo('beauty')}<figcaption><span class="micro">CONTENT WITH PERSONALITY</span><span aria-hidden="true">✳</span></figcaption></figure><div class="service-types">${services.map((s,i)=>`<div class="service-line reveal"><span class="micro">${String(i+1).padStart(2,'0')}</span><h3>${s}</h3><span aria-hidden="true">${i%3===0?'✳':'·'}</span></div>`).join('')}</div></div></div></section>`}
function Gallery(){return `<section class="gallery section" id="gallery"><div class="wrap">${top('06','Фото-контент','LIFE, FRAME BY FRAME')}<div class="gallery-heading reveal"><h2>Оставлю это<br><em>здесь.</em></h2><p>Моменты, детали, настроение.<br>Мой взгляд через объектив.</p></div><div class="photo-collage">${gallery.map((key,i)=>`<figure class="gallery-item gallery-item-${i+1} reveal"><button data-photo="${i}" aria-label="Открыть фото: ${esc(photos[key].alt)}">${photo(key,'(min-width: 900px) 28vw, 50vw')}</button><figcaption class="${i%2?'micro':'handwritten'}">${['little moments','BEAUTY IN DETAILS','городские истории','EVERYDAY LIFE','в своём настроении','A LITTLE FASHION'][i]}</figcaption></figure>`).join('')}<span class="gallery-star" aria-hidden="true">✳</span><span class="gallery-note handwritten" aria-hidden="true">люблю замечать<br>красивое в обычном</span></div></div></section>`}
function Contact(){return `<section class="contact section" id="contact"><div class="wrap">${top('07','Связаться со мной','LET’S CONNECT')}<div class="contact-layout"><div class="contact-copy reveal"><p class="handwritten contact-script">let's create something</p><h2>Давайте создадим<br>что-то <em>классное.</em></h2><p>Готова к сотрудничеству с брендами<br>в нишах бьюти, фешн и лайфстайл.</p><p>Если вам близка моя эстетика и формат контента — буду рада обсудить сотрудничество.</p><div class="social-links">${socials.map(s=>`<a href="${s.href}" ${s.href.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}><span class="micro">${s.name}</span><span>${s.label}</span><span aria-hidden="true">✳</span></a>`).join('')}</div></div><div class="contact-portrait reveal"><figure>${photo('flowers')}<figcaption class="handwritten">с теплом, Лиза</figcaption></figure><span class="contact-star" aria-hidden="true">✳</span></div></div><footer><a class="wordmark" href="#home">лиза*</a><span class="micro">LIFESTYLE & UGC CREATOR</span><a href="#home">Наверх</a></footer></div></section>`}
export function mountSections(target) { target.innerHTML=[About(),Contents(),Niches(),Work(),Services(),Gallery(),Contact()].join(''); }
